/* Anchored orthogonal least-squares fit. Axes are normalized by shared plot ranges. */
function newFitStats(){return Array.from({length:8},()=>({n:0,sum:[0,0,0],products:Array(9).fill(0)}))}
function accumulateFit(stats,m){if(!m.topology)return;for(let k=0;k<8;k++){let s=stats[k],v=[m.topology.meanPath,m.topology.shortCounts[k],m.score];s.n++;for(let i=0;i<3;i++){s.sum[i]+=v[i];for(let j=0;j<3;j++)s.products[i*3+j]+=v[i]*v[j]}}}
function anchoredFit(stats,winner,ranges,sample=[]){if(!stats||!stats.n||!winner)return null;let n=stats.n,w=winner.map((x,i)=>x/ranges[i]),mean=stats.sum.map((x,i)=>x/n/ranges[i]),matrix=Array.from({length:3},(_,i)=>Array.from({length:3},(_,j)=>(stats.products[i*3+j]-winner[i]*stats.sum[j]-winner[j]*stats.sum[i]+n*winner[i]*winner[j])/(ranges[i]*ranges[j]))),trace=matrix[0][0]+matrix[1][1]+matrix[2][2];if(trace<1e-12)return{from:w,to:w,direction:[0,0,0],rms:0,spread:0,n};
// Try every basis vector to handle an exactly zero centroid displacement.
let choices=[];for(let axis=0;axis<3;axis++){let v=[0,0,0];v[axis]=1;for(let it=0;it<36;it++){let next=matrix.map(row=>row.reduce((s,x,j)=>s+x*v[j],0)),norm=Math.hypot(...next);if(norm<1e-15)break;v=next.map(x=>x/norm)}let value=v.reduce((s,x,i)=>s+x*matrix[i].reduce((a,b,j)=>a+b*v[j],0),0);choices.push({v,value})}let {v,value}=choices.sort((a,b)=>b.value-a.value)[0],toward=mean.reduce((s,x,i)=>s+(x-w[i])*v[i],0);if(v[2]<-1e-12||(Math.abs(v[2])<=1e-12&&toward<0))v=v.map(x=>-x);let extent=0;for(let p of sample)extent=Math.max(extent,p.reduce((s,x,i)=>s+(x/ranges[i]-w[i])*v[i],0));if(extent<1e-8)extent=Math.sqrt(Math.max(0,value/n));
// Keep the shown segment within the shared plotting box. It terminates at the winner.
for(let i=0;i<3;i++){if(v[i]>1e-12)extent=Math.min(extent,(1-w[i])/v[i]);if(v[i]<-1e-12)extent=Math.min(extent,-w[i]/v[i])}extent=Math.max(0,extent);return{from:w.map((x,i)=>x+v[i]*extent),to:w,direction:v,rms:Math.sqrt(Math.max(0,(trace-value)/n)),spread:value/trace,n}}
